'use strict';
/**
 * Retrieval layer: chunking, embeddings (with graceful fallback), indexing status and search.
 *
 * Two retrieval modes:
 *  - "embeddings": Gemini embeddings + cosine similarity (best quality).
 *  - "keyword":    BM25-style keyword search over the stored code chunks. Used automatically when the
 *                  Gemini embedding quota is unavailable (very common on the free tier), so the AI
 *                  Mentor keeps working. The chat answer itself is still generated by Gemini.
 */
const { GoogleGenerativeAI } = require('@google/generative-ai');
const Chunk = require('../models/Chunk');
const Project = require('../models/Project');
const { cosineSimilarity, isTestFile, extOf } = require('./scanner');

const EMBED_MODEL = () => process.env.GEMINI_EMBEDDING_MODEL || 'gemini-embedding-001';
const BATCH_SIZE = Number(process.env.EMBED_BATCH_SIZE || 20);
const MAX_CHUNKS_PER_PROJECT = Number(process.env.MAX_CHUNKS_PER_PROJECT || 300);
const CHUNK_LINES = 40;
const CHUNK_OVERLAP = 10;
const MAX_CHUNK_CHARS = 4000;

const sleep = (ms) => new Promise(r => setTimeout(r, ms));

/** Splits text into overlapping line windows, keeping real line numbers. */
const createChunksWithLines = (content) => {
  const lines = content.split('\n');
  const out = [];
  for (let i = 0; i < lines.length; i += (CHUNK_LINES - CHUNK_OVERLAP)) {
    const slice = lines.slice(i, i + CHUNK_LINES);
    const text = slice.join('\n').slice(0, MAX_CHUNK_CHARS);
    if (text.trim()) out.push({ text, startLine: i + 1, endLine: i + slice.length });
    if (i + CHUNK_LINES >= lines.length) break;
  }
  return out;
};

// ---------------------------------------------------------------------------
// Gemini embedding calls
// ---------------------------------------------------------------------------
const getModel = (apiKey) => new GoogleGenerativeAI(apiKey).getGenerativeModel({ model: EMBED_MODEL() });

const embedSingle = async (text, apiKey) => {
  const res = await getModel(apiKey).embedContent({ content: { role: 'user', parts: [{ text }] } });
  const values = res && res.embedding && res.embedding.values;
  if (!Array.isArray(values) || !values.length) throw new Error('Embedding response was empty.');
  return values;
};

const embedBatchRaw = async (texts, apiKey) => {
  const res = await getModel(apiKey).batchEmbedContents({
    requests: texts.map(t => ({ content: { role: 'user', parts: [{ text: t }] } }))
  });
  const vectors = (res.embeddings || []).map(e => e.values);
  if (vectors.length !== texts.length || vectors.some(v => !Array.isArray(v) || !v.length)) {
    throw new Error('Embedding batch returned an unexpected number of vectors.');
  }
  return vectors;
};

/** 'auth' = key/permission problem (do not fall back silently); 'quota' = rate/quota; 'other' = transient. */
const classifyEmbedError = (err) => {
  const m = String((err && err.message) || err || '');
  if (/API key not valid|API_KEY_INVALID|\[40[013] |PERMISSION_DENIED|UNAUTHENTICATED/i.test(m)) return 'auth';
  if (/\[429 |RESOURCE_EXHAUSTED|quota|rate limit|Too Many Requests/i.test(m)) return 'quota';
  return 'other';
};

/** Batch first; if the batch endpoint is refused, embed one by one at a gentle pace. */
const embedBatchResilient = async (texts, apiKey) => {
  try {
    return await embedBatchRaw(texts, apiKey);
  } catch (batchErr) {
    if (classifyEmbedError(batchErr) === 'auth') throw batchErr;
    const vectors = [];
    for (const t of texts) {
      let lastErr = batchErr;
      let ok = false;
      for (let attempt = 1; attempt <= 3 && !ok; attempt++) {
        try { vectors.push(await embedSingle(t, apiKey)); ok = true; }
        catch (e) { lastErr = e; await sleep(attempt === 1 ? 1500 : 20000); }
      }
      if (!ok) throw lastErr;
      await sleep(700); // stay under ~85 requests/minute
    }
    return vectors;
  }
};

const setIndexing = (projectId, patch) => {
  const set = {};
  Object.keys(patch).forEach(k => { set[`indexing.${k}`] = patch[k]; });
  set['indexing.updatedAt'] = new Date();
  return Project.updateOne({ _id: projectId }, { $set: set });
};

// ---------------------------------------------------------------------------
// Keyword (BM25-style) search
// ---------------------------------------------------------------------------
const STOP = new Set(('the a an and or of to in on for with is are was were be this that it its as at by from how what why when where which who ' +
  'do does did can could should would i me my we you your project code file files explain tell about please show give use used using work works').split(' '));

const tokenize = (text) => (String(text).match(/[A-Za-z_$][A-Za-z0-9_$]+|\d{2,}/g) || [])
  .flatMap(t => {
    // split camelCase / snake_case so "authController" also matches "auth" and "controller"
    const parts = t.replace(/([a-z0-9])([A-Z])/g, '$1 $2').split(/[\s_$]+/).filter(Boolean).map(x => x.toLowerCase());
    return parts.length > 1 ? [t.toLowerCase(), ...parts] : [t.toLowerCase()];
  })
  .filter(t => t.length > 1 && !STOP.has(t));

/** @param {Array<{filePath,content,startLine,endLine}>} chunks */
const keywordSearch = (chunks, query, k = 6) => {
  const qTokens = [...new Set(tokenize(query))];
  if (qTokens.length === 0 || chunks.length === 0) return chunks.slice(0, k).map(c => ({ ...c, score: 0 }));

  const docs = chunks.map(c => {
    const tokens = tokenize(`${c.filePath}\n${c.content}`);
    const tf = {};
    tokens.forEach(t => { tf[t] = (tf[t] || 0) + 1; });
    return { c, tf, len: tokens.length || 1, pathTokens: new Set(tokenize(c.filePath)) };
  });
  const avgLen = docs.reduce((a, d) => a + d.len, 0) / docs.length;
  const df = {};
  qTokens.forEach(t => { df[t] = docs.filter(d => d.tf[t]).length; });

  const k1 = 1.4, b = 0.75;
  const scored = docs.map(d => {
    let score = 0;
    qTokens.forEach(t => {
      const f = d.tf[t] || 0;
      if (!f) return;
      const idf = Math.log(1 + (docs.length - df[t] + 0.5) / (df[t] + 0.5));
      score += idf * ((f * (k1 + 1)) / (f + k1 * (1 - b + b * (d.len / avgLen))));
      if (d.pathTokens.has(t)) score += idf * 1.5; // file name/path matches are strong signals
    });
    return { ...d.c, score };
  }).sort((a, b2) => b2.score - a.score);

  const top = scored.slice(0, k);
  const max = top[0] ? top[0].score : 0;
  return top.filter(x => x.score > 0 || max === 0).map(x => ({ ...x, score: max > 0 ? x.score / max : 0 }));
};

// ---------------------------------------------------------------------------
// Indexing
// ---------------------------------------------------------------------------
const insertChunks = (batch, projectId, userId, offset, vectors) => Chunk.insertMany(batch.map((b, j) => ({
  user: userId, project: projectId, filePath: b.path, language: b.language, content: b.text,
  embedding: vectors ? vectors[j] : [], chunkIndex: offset + j, startLine: b.startLine, endLine: b.endLine
})));

/**
 * Indexes the project's source files. Status becomes "ready" only after every chunk is stored.
 * Tries embeddings first; if the Gemini embedding quota is unavailable it finishes in keyword mode.
 */
const indexProject = async ({ projectId, userId, files, apiKey }) => {
  if (!apiKey) {
    await setIndexing(projectId, { status: 'skipped', error: 'GEMINI_API_KEY is not configured; AI chat is unavailable.' });
    return { status: 'skipped' };
  }
  try {
    const planned = [];
    const ordered = [...files].filter(f => !isTestFile(f.path) && !/\.(css|html|sql)$/i.test(f.path)).sort((a, b) => b.importance - a.importance);
    for (const f of ordered) {
      for (const c of createChunksWithLines(f.content)) {
        if (planned.length >= MAX_CHUNKS_PER_PROJECT) break;
        planned.push({ path: f.path, language: extOf(f.path) || 'text', ...c });
      }
      if (planned.length >= MAX_CHUNKS_PER_PROJECT) break;
    }
    await Chunk.deleteMany({ project: projectId });
    if (planned.length === 0) {
      await setIndexing(projectId, { status: 'failed', error: 'No source content to index.' });
      return { status: 'failed' };
    }
    await setIndexing(projectId, { status: 'indexing', mode: 'embeddings', total: planned.length, done: 0, error: '' });

    // Probe the embedding quota with ONE cheap request before doing real work
    let mode = 'embeddings';
    try {
      await embedSingle(planned[0].text, apiKey);
    } catch (probeErr) {
      if (classifyEmbedError(probeErr) === 'auth') {
        await setIndexing(projectId, { status: 'failed', error: 'The Gemini API key was rejected. Check GEMINI_API_KEY in backend/.env.' });
        return { status: 'failed', error: 'auth' };
      }
      console.warn('[RAG-Index] Embeddings unavailable, using keyword search:', String(probeErr.message).slice(0, 160));
      mode = 'keyword';
    }

    let done = 0;
    for (let i = 0; i < planned.length; i += BATCH_SIZE) {
      const batch = planned.slice(i, i + BATCH_SIZE);
      let vectors = null;
      if (mode === 'embeddings') {
        try {
          vectors = await embedBatchResilient(batch.map(b => b.text), apiKey);
        } catch (embedErr) {
          if (classifyEmbedError(embedErr) === 'auth') throw embedErr;
          // Quota ran out part-way: finish in keyword mode (drop vectors so every chunk behaves the same)
          console.warn('[RAG-Index] Embedding quota exhausted mid-way, switching to keyword search.');
          mode = 'keyword';
          await Chunk.updateMany({ project: projectId }, { $set: { embedding: [] } });
        }
      }
      await insertChunks(batch, projectId, userId, i, mode === 'embeddings' ? vectors : null);
      done += batch.length;
      await setIndexing(projectId, { done });
    }
    await setIndexing(projectId, { status: 'ready', mode, done, error: '' });
    return { status: 'ready', mode, chunks: done };
  } catch (err) {
    console.warn('[RAG-Index] failed:', err.message);
    await setIndexing(projectId, { status: 'failed', error: String(err.message).slice(0, 300) });
    return { status: 'failed', error: err.message };
  }
};

// ---------------------------------------------------------------------------
// Retrieval
// ---------------------------------------------------------------------------
const embeddingSearch = async (projectId, userId, queryVec, k) => {
  const best = [];
  const cursor = Chunk.find({ project: projectId, user: userId }).lean().cursor();
  for await (const c of cursor) {
    if (!c.embedding || c.embedding.length === 0) continue;
    const score = cosineSimilarity(queryVec, c.embedding);
    if (best.length < k || score > best[best.length - 1].score) {
      best.push({ score, filePath: c.filePath, content: c.content, startLine: c.startLine, endLine: c.endLine });
      best.sort((a, b) => b.score - a.score);
      if (best.length > k) best.pop();
    }
  }
  return best;
};

/**
 * Returns the most relevant chunks for a question using the project's indexing mode.
 * If embedding the question fails (quota), it transparently falls back to keyword search.
 */
const retrieveChunks = async ({ projectId, userId, question, mode = 'embeddings', apiKey, k = 6 }) => {
  if (mode === 'embeddings') {
    try {
      const vec = await embedSingle(question, apiKey);
      const hits = await embeddingSearch(projectId, userId, vec, k);
      if (hits.length) return { chunks: hits, mode: 'embeddings' };
    } catch (err) {
      console.warn('[RAG] Query embedding failed, using keyword search:', String(err.message).slice(0, 120));
    }
  }
  const all = await Chunk.find({ project: projectId, user: userId }).select('filePath content startLine endLine').lean();
  return { chunks: keywordSearch(all, question, k), mode: 'keyword' };
};

module.exports = {
  indexProject, retrieveChunks, keywordSearch, tokenize, createChunksWithLines, classifyEmbedError, setIndexing,
  embedSingle, BATCH_SIZE, MAX_CHUNKS_PER_PROJECT
};
